  const searchUrl = `https://www.google.com/travel/flights?q=Flights%20from%20JAX%20to%20PHX%20on%20${outDate}%20through%20${retDate}`;
  await tool.navigate({ tabId, url: searchUrl });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "div.JMc5Xc", timeout_ms: 15000 });
  await new Promise(r => setTimeout(r, 2000));

  // 1. Departing options
  const depData = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    return cards.map((c, idx) => ({
      idx,
      label: c.getAttribute('aria-label') || '',
      isNonstop: (c.getAttribute('aria-label') || '').includes('Nonstop'),
      airline: (c.getAttribute('aria-label') || '').match(/flight with ([^.]+)\./)?.[1] || 'Unknown',
      price: (c.getAttribute('aria-label') || '').match(/From (\d+) US dollars/)?.[1] || null
    }));
  });

  const nonstopDep = depData.find(d => d.isNonstop);
  const cheapestDep = depData[0];
  const chosenDep = nonstopDep || cheapestDep;

  console.log(`Departing: ${depData.length} options. Nonstop: ${!!nonstopDep}. Chosen: ${chosenDep?.airline} ($${chosenDep?.price}, nonstop=${chosenDep?.isNonstop})`);

  if (!chosenDep) {
    return { outDate, retDate, nights, error: "No flights found" };
  }

  // Click chosen outbound
  await browserjs(tabId, (idx) => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    if (cards[idx]) cards[idx].click();
  }, chosenDep.idx);

  await tool.wait_for({ tabId, condition: "selector_visible", value: "div.JMc5Xc", timeout_ms: 15000 });
  await new Promise(r => setTimeout(r, 2000));

  // 2. Returning options
  const retData = await browserjs(tabId, () => {
    const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
    return cards.map((c, idx) => ({
      idx,
      label: c.getAttribute('aria-label') || '',
      isNonstop: (c.getAttribute('aria-label') || '').includes('Nonstop'),
      airline: (c.getAttribute('aria-label') || '').match(/flight with ([^.]+)\./)?.[1] || 'Unknown',
      price: (c.getAttribute('aria-label') || '').match(/From (\d+) US dollars/)?.[1] || null
    }));
  });

  const nonstopRet = retData.find(r => r.isNonstop);
  const cheapestRet = retData[0];
  const chosenRet = nonstopRet || cheapestRet;

  console.log(`Returning: ${retData.length} options. Nonstop: ${!!nonstopRet}. Chosen: ${chosenRet?.airline} ($${chosenRet?.price}, nonstop=${chosenRet?.isNonstop})`);

  // Click chosen return
  if (chosenRet) {
    await browserjs(tabId, (idx) => {
      const cards = Array.from(document.querySelectorAll('div.JMc5Xc'));
      if (cards[idx]) cards[idx].click();
    }, chosenRet.idx);

    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });
    await new Promise(r => setTimeout(r, 2500));
  }

  // 3. Extract final summary & booking tiers
  const finalSummary = await browserjs(tabId, () => {
    const text = document.body.innerText;
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    const selIdx = lines.indexOf("Selected flights");
    const bookIdx = lines.findIndex(l => l.startsWith("Booking options"));
    const priceIdx = lines.findIndex(l => l.startsWith("Price insights"));

    return {
      url: window.location.href,
      selectedFlights: selIdx !== -1 && bookIdx !== -1 ? lines.slice(selIdx, bookIdx) : [],
      bookingOptions: bookIdx !== -1 ? lines.slice(bookIdx, priceIdx !== -1 ? priceIdx : bookIdx + 60) : []
    };
  });

  return {
    outDate,
    retDate,
    nights,
    depLabel: chosenDep.label,
    retLabel: chosenRet ? chosenRet.label : null,
    hasNonstopOut: !!nonstopDep,
    hasNonstopRet: !!nonstopRet,
    cheapestDepOverall: cheapestDep,
    finalSummary
  };
}

